-- PostgreSQL twin of migrations/0056_org_orders_brands.sql, generated by scripts/sqlite_to_pg_migration.py

-- Phase 3 — organizations and brands (سازمانی و برندها).
--   * approved purchase request / awarded quote → real order (order_sources, org_order_allocations)
--   * Amazon-Business-style controls: approval thresholds, guided buying, PO reference, buying policy
--   * brand zone: brand verification (official badge) and offer-level pre-orders with deposit
-- Additive only: no existing column, constraint or row changes meaning.
-- Customer PO / reference number carried from the request to the order and its invoice.
ALTER TABLE purchase_requests ADD COLUMN po_reference TEXT;

-- Approval thresholds. A submitted request matches the active rule whose [min, max) band holds its
-- estimated total (highest min wins). auto_approve → approved immediately; require_approvals → N distinct
-- approvers (optionally restricted to one role) before it becomes approved.
CREATE TABLE IF NOT EXISTS org_approval_rules (
    id                  BIGSERIAL PRIMARY KEY,
    organization_id     INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name                TEXT    NOT NULL,
    min_total_minor BIGINT NOT NULL DEFAULT 0 CHECK (min_total_minor >= 0),
    max_total_minor BIGINT CHECK (max_total_minor IS NULL OR max_total_minor > min_total_minor),
    decision            TEXT    NOT NULL CHECK (decision IN ('auto_approve', 'require_approvals')),
    required_approvals  INTEGER NOT NULL DEFAULT 1 CHECK (required_approvals BETWEEN 1 AND 5),
    approver_role       TEXT CHECK (approver_role IS NULL OR approver_role IN
                                    ('organization_admin', 'organization_finance', 'approver')),
    is_active           INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_by_user_id  INTEGER NOT NULL REFERENCES users(id),
    created_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE INDEX IF NOT EXISTS ix_org_approval_rules_org ON org_approval_rules(organization_id, is_active, min_total_minor);

-- Per-organization buying policy: default payment method, prepayment share and guided-buying mode.
CREATE TABLE IF NOT EXISTS org_buying_policies (
    organization_id     BIGINT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,
    payment_method      TEXT    NOT NULL DEFAULT 'credit' CHECK (payment_method IN ('credit', 'prepayment', 'cash')),
    prepayment_bps      INTEGER NOT NULL DEFAULT 0 CHECK (prepayment_bps BETWEEN 0 AND 10000),
    guided_buying       TEXT    NOT NULL DEFAULT 'off' CHECK (guided_buying IN ('off', 'warn', 'enforce')),
    updated_by_user_id  INTEGER REFERENCES users(id),
    updated_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

-- Guided buying: preferred sellers and/or categories (a row with both = that seller for that category).
CREATE TABLE IF NOT EXISTS org_preferred_sellers (
    id                  BIGSERIAL PRIMARY KEY,
    organization_id     INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    supplier_id         INTEGER REFERENCES suppliers(id) ON DELETE CASCADE,
    category_id         INTEGER REFERENCES categories(id) ON DELETE CASCADE,
    note                TEXT,
    created_by_user_id  INTEGER NOT NULL REFERENCES users(id),
    created_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    CHECK (supplier_id IS NOT NULL OR category_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS ix_org_preferred_sellers_org ON org_preferred_sellers(organization_id);

-- Where an order came from and how it is funded, beyond what `orders` stores.
-- One row per order created by Phase 3 (organization conversion or pre-order conversion).
CREATE TABLE IF NOT EXISTS order_sources (
    order_id              BIGINT PRIMARY KEY REFERENCES orders(id) ON DELETE RESTRICT,
    source_kind           TEXT    NOT NULL CHECK (source_kind IN ('purchase_request', 'preorder')),
    organization_id       INTEGER REFERENCES organizations(id),
    purchase_request_id   INTEGER REFERENCES purchase_requests(id),
    supplier_quote_id     INTEGER REFERENCES supplier_quotes(id),
    preorder_id           INTEGER,
    po_reference          TEXT,
    payment_method        TEXT    NOT NULL CHECK (payment_method IN ('credit', 'prepayment', 'cash')),
    prepayment_bps        INTEGER NOT NULL DEFAULT 0 CHECK (prepayment_bps BETWEEN 0 AND 10000),
    credit_minor BIGINT NOT NULL DEFAULT 0 CHECK (credit_minor >= 0),
    cash_due_minor BIGINT NOT NULL DEFAULT 0 CHECK (cash_due_minor >= 0),
    cash_status           TEXT    NOT NULL DEFAULT 'none' CHECK (cash_status IN ('none', 'due', 'paid')),
    cash_reference        TEXT,
    payment_intent_id     INTEGER REFERENCES payment_intents(id),
    fulfillment_plan_json TEXT    NOT NULL,
    fulfillment_released  INTEGER NOT NULL DEFAULT 0 CHECK (fulfillment_released IN (0, 1)),
    idempotency_key       TEXT,
    request_hash          TEXT,
    created_by_user_id    INTEGER NOT NULL REFERENCES users(id),
    created_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    paid_at               TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_order_sources_idem ON order_sources(organization_id, idempotency_key);

CREATE INDEX IF NOT EXISTS ix_order_sources_org ON order_sources(organization_id, created_at);

CREATE INDEX IF NOT EXISTS ix_order_sources_pr ON order_sources(purchase_request_id);

CREATE UNIQUE INDEX IF NOT EXISTS ux_order_sources_preorder ON order_sources(preorder_id);

-- Multi-destination allocation preserved from the purchase request (destination_index NULL = main address).
CREATE TABLE IF NOT EXISTS org_order_allocations (
    id                        BIGSERIAL PRIMARY KEY,
    order_id                  INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    order_item_id             INTEGER NOT NULL REFERENCES order_items(id) ON DELETE CASCADE,
    purchase_request_item_id  INTEGER REFERENCES purchase_request_items(id),
    destination_index         INTEGER,
    destination_label         TEXT,
    province                  TEXT,
    city                      TEXT,
    address                   TEXT,
    recipient_name            TEXT,
    recipient_phone           TEXT,
    quantity                  INTEGER NOT NULL CHECK (quantity > 0)
);

CREATE INDEX IF NOT EXISTS ix_org_order_allocations_order ON org_order_allocations(order_id);

-- Brand verification. The "official" badge is shown only while a registration is verified.
CREATE TABLE IF NOT EXISTS brand_registrations (
    id                    BIGSERIAL PRIMARY KEY,
    supplier_id           INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,
    brand_name            TEXT    NOT NULL,
    trademark_number      TEXT    NOT NULL,
    document_url          TEXT    NOT NULL,
    status                TEXT    NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
    submitted_by_user_id  INTEGER NOT NULL REFERENCES users(id),
    reviewer_user_id      INTEGER REFERENCES users(id),
    review_note           TEXT,
    reviewed_at           TEXT,
    created_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE INDEX IF NOT EXISTS ix_brand_registrations_supplier ON brand_registrations(supplier_id, status);

CREATE INDEX IF NOT EXISTS ix_brand_registrations_status ON brand_registrations(status, id);

CREATE INDEX IF NOT EXISTS ix_brand_registrations_trademark ON brand_registrations(trademark_number);

-- Offer-level pre-order window (پیش‌سفارش).
CREATE TABLE IF NOT EXISTS offer_preorder_windows (
    offer_id              BIGINT PRIMARY KEY REFERENCES seller_offers(id) ON DELETE CASCADE,
    starts_at             TEXT    NOT NULL,
    ends_at               TEXT    NOT NULL,
    expected_ship_date    TEXT    NOT NULL,
    deposit_bps           INTEGER NOT NULL CHECK (deposit_bps BETWEEN 0 AND 10000),
    unit_price_minor BIGINT NOT NULL CHECK (unit_price_minor > 0),
    max_quantity          INTEGER CHECK (max_quantity IS NULL OR max_quantity > 0),
    status                TEXT    NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
    updated_by_user_id    INTEGER REFERENCES users(id),
    created_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    CHECK (ends_at > starts_at)
);

-- A pre-order: price and deposit snapshot; stock is NOT reserved until conversion.
CREATE TABLE IF NOT EXISTS preorders (
    id                    BIGSERIAL PRIMARY KEY,
    preorder_number       TEXT    NOT NULL UNIQUE,
    offer_id              INTEGER NOT NULL REFERENCES seller_offers(id) ON DELETE RESTRICT,
    product_id            INTEGER NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    supplier_id           INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,
    user_id               INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    quantity              INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_minor BIGINT NOT NULL CHECK (unit_price_minor > 0),
    total_minor BIGINT NOT NULL CHECK (total_minor > 0),
    deposit_bps           INTEGER NOT NULL CHECK (deposit_bps BETWEEN 0 AND 10000),
    deposit_minor BIGINT NOT NULL CHECK (deposit_minor >= 0),
    balance_minor BIGINT NOT NULL CHECK (balance_minor >= 0),
    expected_ship_date    TEXT    NOT NULL,
    status                TEXT    NOT NULL DEFAULT 'deposit_due'
                                  CHECK (status IN ('deposit_due', 'deposit_paid', 'converted', 'cancelled')),
    deposit_reference     TEXT,
    deposit_paid_at       TEXT,
    converted_order_id    INTEGER REFERENCES orders(id),
    recipient_name        TEXT    NOT NULL,
    recipient_phone       TEXT    NOT NULL,
    shipping_province     TEXT    NOT NULL,
    shipping_city         TEXT    NOT NULL,
    shipping_line1        TEXT    NOT NULL,
    shipping_postal_code  TEXT,
    idempotency_key       TEXT    NOT NULL,
    created_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at            TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    CHECK (total_minor = unit_price_minor * quantity),
    CHECK (deposit_minor + balance_minor = total_minor),
    UNIQUE (user_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS ix_preorders_offer ON preorders(offer_id, status);

CREATE INDEX IF NOT EXISTS ix_preorders_user ON preorders(user_id, id);
